@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=DM+Sans:wght@400;500;600;700&display=swap');
:root{--ink:#10131c;--paper:#e9e9e5;--muted:#a1a3a9;--orange:#f07835;--orange2:#ff9b54;--line:rgba(255,255,255,.14);--display:'Barlow Condensed',Impact,sans-serif;--body:'DM Sans',Arial,sans-serif}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--ink);color:var(--paper);font-family:var(--body)}button{font:inherit;color:inherit;cursor:pointer}#game{position:relative;width:100%;height:100%;min-height:540px;overflow:hidden;background:radial-gradient(ellipse at 74% 40%,#39373a 0,#1d2027 38%,#10131c 78%)}#arena{position:absolute;inset:0;width:100%;height:100%;z-index:0}.grain{position:absolute;inset:0;pointer-events:none;z-index:1;opacity:.11;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.32'/%3E%3C/svg%3E")}.topbar{position:absolute;z-index:5;left:5.2%;right:5.2%;top:29px;height:40px;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:12px;text-decoration:none;color:var(--paper);font:800 17px var(--display);letter-spacing:1.9px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid var(--orange);color:var(--orange);font:600 19px serif;transform:rotate(-8deg)}.brand-light{font-weight:500;color:#a8a9ad}.top-right{display:flex;align-items:center;gap:27px}.build-tag,.icon-btn{font:600 10px var(--body);letter-spacing:1.5px;color:#c4c5c6}.build-tag i,.ready-dot i{display:inline-block;width:6px;height:6px;border-radius:50%;background:#a7db92;margin-right:8px;box-shadow:0 0 12px #a7db92}.icon-btn{border:0;background:none;color:#eee;font-size:15px}.icon-btn span{font-size:9px;vertical-align:2px;margin-left:4px;letter-spacing:1.2px}.screen{position:absolute;z-index:3;inset:0;display:none}.screen.active