5,255,.13)}.portrait-ring{position:absolute;width:200px;height:80px;border:1px solid rgba(255,255,255,.16);transform:rotate(-29deg)}.portrait-monogram{position:relative;z-index:1;font:900 106px/.8 var(--display);color:#e4a26a;text-shadow:8px 10px 0 rgba(26,22,25,.8),0 0 35px #f3985e65}.portrait-sigil{position:absolute;right:11px;bottom:8px;color:#e3a06a;font:25px serif;opacity:.8}.fighter-meta{flex:1}.fighter-name-row{display:flex;align-items:end;justify-content:space-between}.fighter-name-row small{color:#9699a0;font-size:7px;letter-spacing:1.4px}.fighter-name-row h3{font:800 30px/.95 var(--display);letter-spacing:1.2px;margin-top:4px}.fighter-number{font:700 29px var(--display);color:rgba(240,120,53,.65)}.fighter-meta p{font-size:9px;color:#aeb0b6;line-height:1.45;margin:7px 0 8px}.stats{display:grid;gap:4px}.stat{display:grid;grid-template-columns:43px 1fr 22px;gap:7px;align-items:center;color:#aaa;font:600 7px var(--body);letter-spacing:.8px}.stat-track{height:3px;background:#41444b}.stat-track i{height:100%;display:block;background:var(--orange)}.stat b{font-size:7px;text-align:right;color:#ddd}.fight-btn{width:100%;height:42px;min-height:42px;min-width:0;margin-top:10px;font-size:10px}.back-btn{height:25px;background:none;border:0;color:#a2a3a9;text-align:center;font-size:8px;letter-spacing:1.1px}.select-footer{position:absolute;left:7.3%;right:7.3%;bottom:25px;display:flex;justify-content:space-between;color:#91939a;font-size:8px;letter-spacing:1.2px}.select-footer b{color:#d8d8d6}.select-footer i{color:var(--orange);padding:0 6px;font-style:normal}.fight-ui{position:absolute;z-index:4;inset:0;display:none;pointer-events:none}.fight-ui.active{display:block}.fight-top{position:absolute;top:88px;left:7%;right:7%;display:grid;grid-template-columns:1fr 100px 1fr;gap:23px;align-items:center}.health-block{display:grid;grid-template-columns:1fr;gap:6px}.health-label{display:flex;justify-content:space-between;align-items:baseline;font:700 16px var(--display);letter-spacing:1px}.health-label small{font:600 8px var(--body);letter-spacing:1.2px;color:#b6b7bb}.health-track,.chakra-track{height:11px;background:#282c33;transform:skewX(-15deg);border:1px solid #65676a}.health-track i,.chakra-track i{display:block;height:100%;width:100%;background:linear-gradient(90deg,#d14931,#f28a48);transition:width .2s}.enemy-health .health-track i{background:linear-gradient(90deg,#e58c48,#d44332);float:right}.chakra-track{height:4px;border:0;transform:skewX(-15deg);background:#292c35}.chakra-track i{width:60%;background:#4b9ac4}.enemy-health .chakra-track i{float:right}.round-mark{text-align:center;display:grid;justify-items:center;gap:2px}.round-mark span,.round-mark small{font:600 7px var(--body);letter-spacing:1.4px;color:#c3c2c0}.round-mark b{font:700 30px var(--display);color:#f2eee5;line-height:1}.fight-bottom{pointer-events:auto;position:absolute;left:7%;right:7%;bottom:33px;display:flex;align-items:center;justify-content:space-between}.fight-tip{display:flex;align-items:center;gap:7px;color:#ddd;font-size:8px;letter-spacing:1px}.tip-key{display:grid;place-items:center;width:20px;height:20px;background:#262a31;border:1px solid #68676a;color:#fff;font-weight:700;margin-left:8px}.pause-btn{background:rgba(17,20,27,.7);border:1px solid #74757a;padding:8px 12px;font-size:14px}.pause-btn span{font-size:8px;letter-spacing:1px;margin-left:5px}.fight-message{position:absolute;top:40%;left:50%;transform:translate(-50%,-50%);display:none;text-align:center;text-shadow:0 2px 18px #000;white-space:nowrap}.fight-message.show{display:block;animation:pop .4s ease-out}.fight-message span{display:block;font:800 clamp(30px,5vw,56px) var(--display);letter-spacing:5px;color:#fff}.fight-message b{font:700 30px var(--display);color:var(--orange)}@keyframes pop{from{transform:translate(-50%,-50%) scale(1.4);opacity:0}to{transform:translate(-50%,-50%) scale(1);opacity:1}}.pause-overlay,.result-overlay{pointer-events:auto;position:absolute;inset:0;display:none;place-items:center;background:rgba(9,11,16,.73);backdrop-filter:blur(7px)}.pause-overlay.show,.result-overlay.show{display:grid}.pause-card,.result-card{text-align:center;padding:35px 48px;background:linear-gradient(150deg,#292a30,#181b23);border:1px solid #ffffff25;box-shadow:0 20px 70px #0008;min-width:280px}.pause-card small{color:#adaeb4;font-size:8px;letter-spacing:2px}.pause-card h2,.result-card h2{font:800 54px/.95 var(--display);margin:9px 0 22px}.pause-card .primary-btn,.result-card .primary-btn{margin:0 auto 15px}.pause-card .text-btn,.result-card .text-btn{margin:5px auto}.result-card p{color:#b8b9bc;font-size:12px;margin:-10px 0 22px}.result-card h2{color:var(--orange)}.touch-controls{display:none;pointer-events:auto;position:absolute;bottom:88px;left:5%;right:5%;justify-content:space-between;align-items:end}.touch-pad{width:135px;height:100px;display:grid;grid-template:repeat(2,1fr)/repeat(3,1fr);gap:4px}.touch-pad button,.touch-actions button{border:1px solid #ffffff4a;background:#20232bc9;border-radius:8px;backdrop-filter:blur(4px);font:700 15px var(--body);touch-action:none}.touch-pad button:nth-child(1){grid-column:2}.touch-pad button:nth-child(2){grid-column:1;grid-row:2}.touch-pad button:nth-child(3){grid-column:2;grid-row:2}.touch-pad button:nth-child(4){grid-column:3;grid-row:2}.touch-actions{display:grid;grid-template-columns:repeat(2,53px);grid-template-rows:repeat(2,48px);gap:7px}.touch-actions button{font-size:9px;letter-spacing:.5px}.touch-actions .touch-jutsu{background:#b84931d9}.touch-actions .touch-attack{background:#b46a31d9}.touch-controls button:active,.touch-controls button.pressed{filter:brightness(1.6);transform:scale(.94)}
