y:block;font-size:7px;line-height:1.8}.select-footer span:last-child{display:block;color:#777}.fight-top{top:67px;left:4%;right:4%;grid-template-columns:1fr 53px 1fr;gap:8px}.health-label{font-size:13px}.health-label small{font-size:6px}.health-track{height:8px}.round-mark span,.round-mark small{font-size:5px;letter-spacing:.7px}.round-mark b{font-size:25px}.fight-bottom{left:5%;right:5%;bottom:16px}.fight-tip{display:none}.touch-controls{display:flex}.pause-btn{font-size:13px}.pause-btn span{font-size:7px}.pause-overlay,.result-overlay{z-index:5}.pause-card,.result-card{padding:28px 30px}}
